local ActivityMountainMainLineCell = Class('ActivityMountainMainLineCell')
local ActivityCakeUtils = import('Game.UI.ActivityCakeShopDialog.ActivityCakeUtils')
function ActivityMountainMainLineCell:__init()

end

function ActivityMountainMainLineCell:__delete()

end

function ActivityMountainMainLineCell:Awake()
	SetButtonAction(self.Root.gameObject,Bind(self,self.OnBtnNodeClick))
end

function ActivityMountainMainLineCell:SetLuaIndexAndData(index,data)
	self.index = index
	self.data = data
	self:RefreshShow()
end

function ActivityMountainMainLineCell:RefreshShow()
	local showIndex = checkNumber(self.index) >=10 and self.index or "0"..self.index
	self.showIndex = showIndex
	
	CfUtils.FillText(self.UnSelectChapter,showIndex)
	CfUtils.FillText(self.UnSelectDesc,self.data.name)
	
	CfUtils.SetActive(self.ImgType, self.data.type == ActivityCakeUtils.ChapterType.Battle)
	CfUtils.SetUISwitchImage(self.ImgTitleIcon, self.data.type)
	
	
	self:RefreshIsPass()
	self:RefreshLockState()
end

function ActivityMountainMainLineCell:GetIsUnLock()
	local isUnLock = false
	if self.data.unlockLevel == 0 then
		isUnLock = true
	else
		isUnLock = ActivityCakeUtils.IsPassChapter(self.data.unlockLevel)
	end
	return isUnLock
end

function ActivityMountainMainLineCell:RefreshIsPass()
	local isPass = ActivityCakeUtils.IsPassChapter(self.data.id)
	CfUtils.SetActive(self.StatusFinish.gameObject,isPass)
end

function ActivityMountainMainLineCell:RefreshLockState()
	
	local isUnLock = self:GetIsUnLock()
	KTool.SetActive(self.StatusLock.gameObject,not isUnLock)
	
	if not isUnLock then
		CfUtils.SetActive(self.Select.gameObject,false)
		CfUtils.SetActive(self.Unselect.gameObject,true)
		CfUtils.FillText(self.UnSelectChapter,"")
		CfUtils.PlayAnimation(self.Root,"ActivityMountainMainLineDetailsDialog_CellDefualt")
	else
		
		CfUtils.FillText(self.UnSelectChapter,self.showIndex)
		CfUtils.FillText(self.UnSelectDesc,self.data.name)
		CfUtils.FillText(self.SelectChapter,self.showIndex)
		CfUtils.FillText(self.SelectDesc,self.data.name)
	end
end

function ActivityMountainMainLineCell:OnBtnNodeClick()
	if not self:GetIsUnLock() then
		GameUtils.Toast(localize("请先通关前置关卡"))
		return
	end
	
	if not isNull(self.callBack) then
		self.callBack(self.index)
	end
end

function ActivityMountainMainLineCell:SetClickCB(cb)
	self.callBack = cb
end

function ActivityMountainMainLineCell:PlayDelayAnimByShow(delayIndex)
	CfUtils.PlayDelayShowAnimation(self.controller, delayIndex, 'UI_List_Cell_ActivityMountainShow')
end

function ActivityMountainMainLineCell:PlayAnimByIdle()
	CfUtils.PlayAnimation(self.controller, 'UI_Common_List_Cell_Idle')
end

function ActivityMountainMainLineCell:OnSelect()
	CfUtils.PlayAnimation(self.Root,"ActivityMountainMainLineDetailsDialog_CellSelect")
	CfUtils.SetActive(self.Select.gameObject,true)
	CfUtils.SetActive(self.Unselect.gameObject,false)
end

function ActivityMountainMainLineCell:DoSelect()
	CfUtils.PlayAnimation(self.Root,"ActivityMountainMainLineDetailsDialog_CellBack")
	CfUtils.SetActive(self.Select.gameObject,false)
	CfUtils.SetActive(self.Unselect.gameObject,true)
end



function ActivityMountainMainLineCell:OnDestroy()
	self.controller = nil--luabehaviour 中CSharp对象
	self:Delete()
end

return ActivityMountainMainLineCell